package com.fathom.liability; import com.fathom.common.BaseEntity; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="liabilities") public class Liability extends BaseEntity { @Id private UUID id; @Column(name="user_id",nullable=false) private UUID userId; @Enumerated(EnumType.STRING) @Column(name="liability_type",nullable=false) private LiabilityType liabilityType; @Column(nullable=false) private String name; private String lender; @Column(length=3,nullable=false) private String currency="INR"; @Column(name="principal_amount",precision=19,scale=4) private BigDecimal principalAmount; @Column(name="outstanding_amount",nullable=false,precision=19,scale=4) private BigDecimal outstandingAmount; @Column(name="interest_rate",precision=8,scale=4) private BigDecimal interestRate; @Column(name="emi_amount",precision=19,scale=4) private BigDecimal emiAmount; @Column(name="start_date") private LocalDate startDate; @Column(name="end_date") private LocalDate endDate; @Column(nullable=false) private boolean active=true; @PrePersist void init(){if(id==null)id=UUID.randomUUID();} public UUID getId(){return id;} public UUID getUserId(){return userId;} public LiabilityType getLiabilityType(){return liabilityType;} public String getName(){return name;} public String getLender(){return lender;} public String getCurrency(){return currency;} public BigDecimal getPrincipalAmount(){return principalAmount;} public BigDecimal getOutstandingAmount(){return outstandingAmount;} public BigDecimal getInterestRate(){return interestRate;} public BigDecimal getEmiAmount(){return emiAmount;} public LocalDate getStartDate(){return startDate;} public LocalDate getEndDate(){return endDate;} public boolean isActive(){return active;} public void setUserId(UUID v){userId=v;} public void setLiabilityType(LiabilityType v){liabilityType=v;} public void setName(String v){name=v;} public void setLender(String v){lender=v;} public void setCurrency(String v){currency=v;} public void setPrincipalAmount(BigDecimal v){principalAmount=v;} public void setOutstandingAmount(BigDecimal v){outstandingAmount=v;} public void setInterestRate(BigDecimal v){interestRate=v;} public void setEmiAmount(BigDecimal v){emiAmount=v;} public void setStartDate(LocalDate v){startDate=v;} public void setEndDate(LocalDate v){endDate=v;} public void setActive(boolean v){active=v;} }
